extends Node3D
## A voxel horse built from small cubes, with a procedural gallop.
## Controls: W/Up accelerate, S/Down brake, A/D or Left/Right steer, Space jump.

const VOX := 0.1  # world size of one voxel
const MAX_SPEED := 12.0
const ACCEL := 9.0
const BRAKE := 14.0
const FRICTION := 3.0
const TURN_RATE := 2.0  # radians per second at full steering
const GRAVITY := 22.0
const JUMP_VELOCITY := 7.0
const BOUNDS := 140.0
# Diagonal pairs move together: front-left/back-right, then front-right/back-left
const LEG_PHASE := [0.0, PI, PI, 0.0]

var speed := 0.0
var phase := 0.0

var _vertical_velocity := 0.0
var _body: Node3D
var _head: Node3D
var _tail: Node3D
var _legs: Array[Node3D] = []
var _body_base_y := 0.47 * VOX  # lifts the feet so they rest on y = 0
var _mesh: BoxMesh
var _materials := {}
var _rng := RandomNumberGenerator.new()


func _ready() -> void:
	_rng.seed = 7
	_mesh = BoxMesh.new()
	_mesh.size = Vector3.ONE * VOX * 0.94  # small gaps give the blocky voxel look
	_build_horse()


func _process(delta: float) -> void:
	_steer(delta)
	_animate(delta)


func _steer(delta: float) -> void:
	var accelerate := Input.is_key_pressed(KEY_W) or Input.is_key_pressed(KEY_UP)
	var brake := Input.is_key_pressed(KEY_S) or Input.is_key_pressed(KEY_DOWN)
	var left := Input.is_key_pressed(KEY_A) or Input.is_key_pressed(KEY_LEFT)
	var right := Input.is_key_pressed(KEY_D) or Input.is_key_pressed(KEY_RIGHT)

	if accelerate:
		speed = move_toward(speed, MAX_SPEED, ACCEL * delta)
	elif brake:
		speed = move_toward(speed, 0.0, BRAKE * delta)
	else:
		speed = move_toward(speed, 0.0, FRICTION * delta)

	# Positive yaw turns left; the horse can only steer properly while moving
	var turn := float(left) - float(right)
	rotation.y += turn * TURN_RATE * clampf(speed / 4.0, 0.0, 1.0) * delta

	var forward := -transform.basis.z
	position += forward * speed * delta
	position.x = clampf(position.x, -BOUNDS, BOUNDS)
	position.z = clampf(position.z, -BOUNDS, BOUNDS)

	# Simple jump: a vertical velocity under gravity, clamped to the ground
	if position.y <= 0.0:
		position.y = 0.0
		_vertical_velocity = 0.0
		if Input.is_key_pressed(KEY_SPACE):
			_vertical_velocity = JUMP_VELOCITY
	_vertical_velocity -= GRAVITY * delta
	position.y = maxf(position.y + _vertical_velocity * delta, 0.0)


func _animate(delta: float) -> void:
	var intensity := clampf(speed / MAX_SPEED, 0.0, 1.0)
	phase += delta * lerpf(0.0, 12.0, intensity)

	# Legs tuck up a little while airborne
	var swing := intensity * (0.3 if position.y > 0.01 else 0.7)
	for i in _legs.size():
		_legs[i].rotation.x = sin(phase + LEG_PHASE[i]) * swing

	# Body rises on each stride and leans into the gallop
	_body.position.y = _body_base_y + absf(sin(phase)) * 0.12 * intensity
	_body.rotation.x = -0.06 * intensity

	_head.rotation.x = -0.25 + sin(phase * 2.0) * 0.04 * intensity
	_tail.rotation.x = -0.3 - 0.3 * intensity + sin(phase) * 0.1 * intensity
	_tail.rotation.y = sin(phase * 0.5) * 0.2


func _build_horse() -> void:
	var brown := Color(0.5, 0.31, 0.16)
	var dark := Color(0.22, 0.13, 0.07)
	var light := Color(0.78, 0.6, 0.4)
	var red := Color(0.7, 0.12, 0.12)
	var black := Color(0.04, 0.04, 0.04)
	var hoof := Color(0.1, 0.08, 0.06)

	# Everything is addressed in voxel cell units; each part has a pivot origin
	_body = Node3D.new()
	_body.position.y = _body_base_y
	add_child(_body)

	# Torso, saddle, neck and mane are part of the body so they bob together
	_fill(_body, Vector3.ZERO, Vector3i(-3, 6, -6), Vector3i(2, 9, 4), brown)
	_fill(_body, Vector3.ZERO, Vector3i(-2, 10, -2), Vector3i(1, 10, 1), red)
	_fill(_body, Vector3.ZERO, Vector3i(-2, 9, -9), Vector3i(1, 13, -7), brown)
	_fill(_body, Vector3.ZERO, Vector3i(0, 14, -9), Vector3i(0, 14, -7), dark)

	# Head pivots at the base of the neck so it can nod
	var head_origin := Vector3(-0.5, 12.0, -8.0)
	var eyes := [Vector3i(-2, 14, -10), Vector3i(1, 14, -10)]
	_head = Node3D.new()
	_head.position = head_origin * VOX
	_body.add_child(_head)
	_fill(_head, head_origin, Vector3i(-2, 13, -11), Vector3i(1, 15, -9), brown, eyes)
	_fill(_head, head_origin, Vector3i(-1, 13, -13), Vector3i(0, 14, -12), light)
	_fill(_head, head_origin, Vector3i(-1, 16, -10), Vector3i(0, 16, -9), dark)
	for eye in eyes:
		_fill(_head, head_origin, eye, eye, black)

	# Four legs, each pivoting at the hip. Each entry is the leg's lower-left cell (x, z)
	for spec in [[-3, -5], [1, -5], [-3, 2], [1, 2]]:
		var x0: int = spec[0]
		var z0: int = spec[1]
		var origin := Vector3(x0 + 0.5, 5.5, z0 + 0.5)
		var leg := Node3D.new()
		leg.position = origin * VOX
		_body.add_child(leg)
		_legs.append(leg)
		_fill(leg, origin, Vector3i(x0, 1, z0), Vector3i(x0 + 1, 5, z0 + 1), brown)
		_fill(leg, origin, Vector3i(x0, 0, z0), Vector3i(x0 + 1, 0, z0 + 1), hoof)

	# Tail pivots at the top of the rump
	var tail_origin := Vector3(-0.5, 9.5, 4.5)
	_tail = Node3D.new()
	_tail.position = tail_origin * VOX
	_body.add_child(_tail)
	_fill(_tail, tail_origin, Vector3i(-1, 5, 5), Vector3i(0, 9, 6), dark)


## Places one voxel per cell in the inclusive range lo..hi, attached to `parent`.
## `origin` is the parent's pivot in cell units; cells in `skip` are left out.
func _fill(parent: Node3D, origin: Vector3, lo: Vector3i, hi: Vector3i, color: Color, skip: Array = []) -> void:
	for x in range(lo.x, hi.x + 1):
		for y in range(lo.y, hi.y + 1):
			for z in range(lo.z, hi.z + 1):
				var cell := Vector3i(x, y, z)
				if cell in skip:
					continue
				var voxel := MeshInstance3D.new()
				voxel.mesh = _mesh
				voxel.material_override = _material(color)
				voxel.position = (Vector3(cell) - origin) * VOX
				parent.add_child(voxel)


## Returns a cached material with one of three slight shade variations.
func _material(color: Color) -> StandardMaterial3D:
	var shade := _rng.randi_range(0, 2)
	var key := "%s_%d" % [color.to_html(), shade]
	if not _materials.has(key):
		var factor: float = [0.92, 1.0, 1.08][shade]
		var mat := StandardMaterial3D.new()
		mat.albedo_color = Color(color.r * factor, color.g * factor, color.b * factor)
		mat.roughness = 0.9
		_materials[key] = mat
	return _materials[key]

extends Node3D
## World setup: sky, sun, voxel scenery, collectible carrots, camera and HUD.

const HorseScript := preload("res://voxel_horse.gd")
const CARROT_COUNT := 8
const PICKUP_RADIUS := 1.6
const WORLD_HALF_SIZE := 140.0
const TREE_COUNT := 70
const TUFT_COUNT := 1500
const SCENERY_VOX := 0.5  # size of one tree voxel

var horse
var camera: Camera3D
var carrots: Array[Node3D] = []
var score := 0

var _hud_label: Label
var _time := 0.0
var _rng := RandomNumberGenerator.new()


func _ready() -> void:
	_rng.seed = 2026
	_build_environment()
	_build_ground()
	_build_scenery()

	horse = HorseScript.new()
	add_child(horse)

	for i in CARROT_COUNT:
		var carrot := _make_carrot()
		add_child(carrot)
		_respawn_carrot(carrot)
		carrots.append(carrot)

	camera = Camera3D.new()
	camera.fov = 70.0
	add_child(camera)
	camera.position = Vector3(0.0, 3.0, 7.0)

	_build_hud()


func _process(delta: float) -> void:
	_time += delta
	_update_carrots()
	_update_camera(delta)
	_hud_label.text = "Carrots: %d    Speed: %.1f" % [score, horse.speed]


func _build_environment() -> void:
	var sky_material := ProceduralSkyMaterial.new()
	sky_material.sky_top_color = Color(0.3, 0.55, 0.9)
	sky_material.sky_horizon_color = Color(0.75, 0.85, 0.95)
	sky_material.ground_horizon_color = Color(0.75, 0.85, 0.95)
	sky_material.ground_bottom_color = Color(0.2, 0.35, 0.15)

	var sky := Sky.new()
	sky.sky_material = sky_material

	var environment := Environment.new()
	environment.background_mode = Environment.BG_SKY
	environment.sky = sky
	environment.ambient_light_source = Environment.AMBIENT_SOURCE_SKY
	environment.ambient_light_energy = 0.7

	var world_environment := WorldEnvironment.new()
	world_environment.environment = environment
	add_child(world_environment)

	var sun := DirectionalLight3D.new()
	sun.rotation_degrees = Vector3(-55.0, -35.0, 0.0)
	sun.shadow_enabled = true
	add_child(sun)


func _build_ground() -> void:
	var plane := PlaneMesh.new()
	plane.size = Vector2(300.0, 300.0)
	plane.material = _solid(Color(0.3, 0.58, 0.25))
	var ground := MeshInstance3D.new()
	ground.mesh = plane
	add_child(ground)


## Trees and grass tufts are batched into a single MultiMesh for performance.
func _build_scenery() -> void:
	var cubes: Array = []  # entries of [Transform3D, Color]
	var trunk := Color(0.42, 0.26, 0.13)
	var leaves := [Color(0.18, 0.46, 0.2), Color(0.24, 0.55, 0.22)]

	for i in TREE_COUNT:
		var base := Vector3(
			_rng.randf_range(-WORLD_HALF_SIZE, WORLD_HALF_SIZE),
			0.0,
			_rng.randf_range(-WORLD_HALF_SIZE, WORLD_HALF_SIZE))
		if absf(base.x) < 8.0 and absf(base.z) < 8.0:
			continue  # keep the start area clear
		for y in 4:
			_add_cube(cubes, base + Vector3(0.0, (y + 0.5) * SCENERY_VOX, 0.0), trunk)
		for y in range(4, 7):
			var radius := 2 if y == 5 else 1
			for dx in range(-radius, radius + 1):
				for dz in range(-radius, radius + 1):
					var pos := base + Vector3(dx, y + 0.5, dz) * SCENERY_VOX
					_add_cube(cubes, pos, leaves[_rng.randi_range(0, 1)])

	for i in TUFT_COUNT:
		var pos := Vector3(
			_rng.randf_range(-WORLD_HALF_SIZE, WORLD_HALF_SIZE),
			0.05,
			_rng.randf_range(-WORLD_HALF_SIZE, WORLD_HALF_SIZE))
		_add_cube(cubes, pos, leaves[_rng.randi_range(0, 1)].darkened(_rng.randf_range(0.0, 0.2)), 0.12)

	_add_multimesh(cubes)


func _add_cube(cubes: Array, pos: Vector3, color: Color, size: float = SCENERY_VOX) -> void:
	var basis := Basis.from_scale(Vector3.ONE * size * 0.95)
	cubes.append([Transform3D(basis, pos), color])


func _add_multimesh(cubes: Array) -> void:
	var mesh := BoxMesh.new()
	mesh.size = Vector3.ONE
	var mat := StandardMaterial3D.new()
	mat.vertex_color_use_as_albedo = true
	mat.roughness = 0.9
	mesh.material = mat

	var multimesh := MultiMesh.new()
	multimesh.transform_format = MultiMesh.TRANSFORM_3D
	multimesh.use_colors = true
	multimesh.mesh = mesh
	multimesh.instance_count = cubes.size()
	for i in cubes.size():
		multimesh.set_instance_transform(i, cubes[i][0])
		multimesh.set_instance_color(i, cubes[i][1])

	var node := MultiMeshInstance3D.new()
	node.multimesh = multimesh
	add_child(node)


func _make_carrot() -> Node3D:
	var carrot := Node3D.new()
	carrot.set_meta("bob_phase", _rng.randf() * TAU)

	var root := MeshInstance3D.new()
	var root_box := BoxMesh.new()
	root_box.size = Vector3(0.22, 0.22, 0.6)
	root.mesh = root_box
	root.material_override = _solid(Color(1.0, 0.5, 0.1))
	carrot.add_child(root)

	var leaf := MeshInstance3D.new()
	var leaf_box := BoxMesh.new()
	leaf_box.size = Vector3(0.2, 0.3, 0.2)
	leaf.mesh = leaf_box
	leaf.material_override = _solid(Color(0.2, 0.7, 0.2))
	leaf.position = Vector3(0.0, 0.2, 0.4)
	carrot.add_child(leaf)
	return carrot


func _respawn_carrot(carrot: Node3D) -> void:
	var angle := _rng.randf() * TAU
	var dist := _rng.randf_range(12.0, 30.0)
	var center: Vector3 = horse.position
	var x := clampf(center.x + cos(angle) * dist, -WORLD_HALF_SIZE, WORLD_HALF_SIZE)
	var z := clampf(center.z + sin(angle) * dist, -WORLD_HALF_SIZE, WORLD_HALF_SIZE)
	carrot.position = Vector3(x, 0.6, z)
	carrot.rotation.y = _rng.randf() * TAU


func _update_carrots() -> void:
	for carrot in carrots:
		# Gentle bob so the pickups are easy to spot
		var phase: float = carrot.get_meta("bob_phase")
		carrot.position.y = 0.6 + sin(_time * 3.0 + phase) * 0.1
		carrot.rotation.y += 0.02

		var offset: Vector3 = horse.position - carrot.position
		offset.y = 0.0
		if offset.length() < PICKUP_RADIUS:
			score += 1
			_respawn_carrot(carrot)


func _update_camera(delta: float) -> void:
	# Local +Z points behind the horse, so the camera trails it and lags on turns
	var behind: Vector3 = horse.transform.basis.z
	var target: Vector3 = horse.position + behind * 7.0 + Vector3.UP * 3.0
	camera.position = camera.position.lerp(target, 1.0 - exp(-6.0 * delta))
	camera.look_at(horse.position + Vector3.UP * 1.2, Vector3.UP)


func _build_hud() -> void:
	var layer := CanvasLayer.new()
	add_child(layer)

	_hud_label = Label.new()
	_hud_label.set_anchors_and_offsets_preset(Control.PRESET_TOP_LEFT)
	_hud_label.position = Vector2(16.0, 12.0)
	_hud_label.add_theme_font_size_override("font_size", 24)
	_hud_label.add_theme_color_override("font_outline_color", Color.BLACK)
	_hud_label.add_theme_constant_override("outline_size", 6)
	layer.add_child(_hud_label)

	var help := Label.new()
	help.text = "W/Up: gallop   S/Down: brake   A/D or Left/Right: steer   Space: jump"
	help.set_anchors_and_offsets_preset(Control.PRESET_BOTTOM_LEFT)
	help.position.y -= 36.0
	help.position.x = 16.0
	help.add_theme_font_size_override("font_size", 18)
	help.add_theme_color_override("font_outline_color", Color.BLACK)
	help.add_theme_constant_override("outline_size", 5)
	layer.add_child(help)


func _solid(color: Color) -> StandardMaterial3D:
	var mat := StandardMaterial3D.new()
	mat.albedo_color = color
	mat.roughness = 0.9
	return mat
